import pytest
from operations import Calculator

@pytest.fixture
def calc() -> Calculator:
    return Calculator()

def test_add(calc: Calculator) -> None:
    assert calc.add(5, 3) == 8.0
    assert calc.add(-1, 1) == 0.0

def test_subtract(calc: Calculator) -> None:
    assert calc.subtract(10, 4) == 6.0
    assert calc.subtract(0, 5) == -5.0

def test_multiply(calc: Calculator) -> None:
    assert calc.multiply(3, 4) == 12.0
    assert calc.multiply(-2, 3) == -6.0

def test_divide(calc: Calculator) -> None:
    assert calc.divide(10, 2) == 5.0
    assert calc.divide(5, 2) == 2.5

def test_divide_zero(calc: Calculator) -> None:
    with pytest.raises(ValueError, match="Division by zero"):
        calc.divide(10, 0)

def test_power_and_modulo(calc: Calculator) -> None:
    assert calc.power(2, 3) == 8.0
    assert calc.modulo(10, 3) == 1.0

def test_modulo_zero(calc: Calculator) -> None:
    with pytest.raises(ValueError, match="Modulo by zero"):
        calc.modulo(10, 0)

def test_history_copy_integrity(calc: Calculator) -> None:
    calc.add(1, 1)
    history = calc.get_history()
    history.append(("malicious", 999.0, 999.0, 999.0))
    assert len(calc.get_history()) == 1
    assert calc.get_history() != history

