    # Per requirements, evaluate catches ZDE and converts to ValueError
    with pytest.raises(ValueError, match="Division/Modulo by zero"):
        calc.evaluate("10 / 0")

def test_evaluate_unsupported(calc: Calculator) -> None:
    with pytest.raises(ValueError, match="Invalid expression"):
        calc.evaluate("abs(1)")

